// ------ Utils ------

// Routing

export { type RouteDefinition, defineRoute, removeRoute } from "./utils/route.ts";
export type { BuiltinRouteRules, ResolvedRouteRules, RouteRules } from "./types/route-rules.ts";

// Request

export {
  requestWithURL,
  requestWithBaseURL,
  toRequest,
  getRequestHost,
  getRequestIP,
  getRequestProtocol,
  getRequestURL,
  isMethod,
